    43	function events(){const e=new EventSource('/api/events?sessionId='+S.sid);S.events=e;e.addEventListener('presence',x=>{S.presence=JSON.parse(x.data);showPresence()});e.addEventListener('revision',x=>remoteRevision(JSON.parse(x.data)));e.onerror=()=>{$('presence-summary').textContent='Reconnecting live views…'}}
    44	function showPresence(){const count=new Map();S.presence.forEach(p=>count.set(p.name,(count.get(p.name)||0)+1));$('presence-summary').textContent=`${S.presence.length} live view${S.presence.length===1?'':'s'} · ${[...count].map(([n,c])=>`${n} (${c})`).join(', ')}`;$('presence-legend').innerHTML=S.presence.map(p=>`<span class="presence-chip" style="--color:${p.color}"><i class="presence-dot"></i>${esc(p.name)} · ${p.selection}</span>`).join('');remote()}
    45	function remote(){ui.grid.querySelectorAll('.remote-outline').forEach(x=>x.remove());for(const p of S.presence.filter(x=>x.id!==S.sid)){const[s,z=s]=p.selection.split(':'),b=bounds({start:s,end:z}),e=document.createElement('div');e.className='remote-outline';e.style.setProperty('--color',p.color);e.style.left=44+b.c1*112+'px';e.style.top=30+b.r1*28+'px';e.style.width=(b.c2-b.c1+1)*112+'px';e.style.height=(b.r2-b.r1+1)*28+'px';e.title=p.name+': '+p.selection;ui.grid.append(e)}}
    46	function remoteRevision(d){if(d.sessionId===S.sid||d.revision<=S.rev)return;const oldSaved=copy(S.saved),drafts=[];if(S.dirty){const all=new Set([...Object.keys(sheet().cells),...Object.keys(oldSaved.sheets[0].cells)]);for(const a of all)if(raw(a)!==(oldSaved.sheets[0].cells[a]??''))drafts.push([a,raw(a)])}S.saved=copy(d.workbook);S.book=copy(d.workbook);S.rev=d.revision;drafts.forEach(([a,v])=>{put(a,v);if(d.changed.some(x=>x.address===a))S.conflicts.add(a)});S.dirty=!!drafts.length;render();revisions();history()}
    47	async function history(){if(!S.book)return;const a=S.sel.end,d=await request(`/api/workbooks/ops-plan/history/plan/${a}`).catch(()=>null);if(!d)return;$('history-address').textContent=a;$('last-changed').textContent=d.lastChangedBy?`Last changed by ${d.lastChangedBy.name} · ${new Date(d.lastChangedBy.changedAt).toLocaleString()}`:'No saved changes to this cell';$('cell-history').innerHTML=d.changes.map(x=>`<li><strong>Revision ${x.revision} · ${esc(x.name)}</strong><span class="muted">${new Date(x.changedAt).toLocaleString()}</span><br><code>${esc(x.previousValue||'(blank)')} → ${esc(x.newValue||'(blank)')}</code></li>`).join('')}
    48	async function revisions(){const d=await request('/api/workbooks/ops-plan/revisions');$('revision-history').innerHTML=d.revisions.map(x=>`<li><button data-preview="${x.revision}"><strong>Revision ${x.revision}</strong>${new Date(x.createdAt).toLocaleString()} · ${esc(x.name||'Initial seed')}</button><div class="history-actions"><button data-preview="${x.revision}">Preview</button><button data-restore="${x.revision}">Restore as draft</button></div></li>`).join('')}
    49	async function preview(n){const d=await request(`/api/workbooks/ops-plan/revisions/${n}`);if(!S.preview)S.preview=copy(S.book);S.book=copy(d.workbook);$('close-preview').hidden=false;$('preview-note').textContent=`Previewing revision ${n}. Live content and dirty state are unchanged.`;render();status('Previewing revision '+n)}function closePreview(){if(!S.preview)return;S.book=S.preview;S.preview=null;$('close-preview').hidden=true;$('preview-note').textContent='Preview or restore a saved revision.';render()}
    50	async function restore(n){if(S.preview)closePreview();const d=await request(`/api/workbooks/ops-plan/revisions/${n}`),x=[],target=d.workbook.sheets[0].cells;for(const a of new Set([...Object.keys(sheet().cells),...Object.keys(target)]))x.push([a,target[a]??'']);tx(x);status(`Revision ${n} restored as unsaved draft`)}
